'use strict';

// MODULES //

var limits = require( '@data-apis/limits' );
var fetchBounded = require( '@data-apis/http/fetch-bounded' );
var fetchJson = require( '@data-apis/http/fetch-json' );
var HarvesterError = require( '@data-apis/errors/harvester-error' );
var sha256 = require( '@data-apis/canonical/sha256' );
var normalizeTimestamp = require( '@data-apis/report/normalize-timestamp' );


// VARIABLES //

var API_ROOT = 'https://api.github.com';
var API_VERSION = '2022-11-28';
var ALLOWED_EVENTS = new Set( [
	'push',
	'schedule',
	'workflow_dispatch'
] );


// FUNCTIONS //

/**
* Creates GitHub REST API headers.
*
* @private
* @param {string} token - access token
* @returns {Object} headers
*/
function apiHeaders( token ) {
	var headers = {
		'accept': 'application/vnd.github+json',
		'x-github-api-version': API_VERSION,
		'user-agent': 'array-api-compliance-harvester'
	};

	if ( token ) {
		headers.authorization = 'Bearer ' + token;
	}
	return headers;
}

/**
* Resolves the least-privilege token for a source.
*
* @private
* @param {Object} source - source definition
* @param {Object} env - environment
* @returns {string|undefined} token
*/
function tokenFor( source, env ) {
	if ( source.project.toLowerCase() === String( env.GITHUB_REPOSITORY || '' ).toLowerCase() ) {
		return env.GITHUB_TOKEN;
	}
	return env.HARVEST_GITHUB_TOKEN;
}

/**
* Compares trusted runs newest-first.
*
* @private
* @param {Object} left - run
* @param {Object} right - run
* @returns {number} ordering
*/
function compareRuns( left, right ) {
	var value = Date.parse( right.run_started_at ) - Date.parse( left.run_started_at );

	if ( value !== 0 ) {
		return value;
	}
	value = Number( right.id ) - Number( left.id );
	if ( value !== 0 ) {
		return value;
	}
	return Number( right.run_attempt || 1 ) - Number( left.run_attempt || 1 );
}

/**
* Fetches JSON from GitHub.
*
* @private
* @param {string} route - API route
* @param {Object} options - request options
* @returns {Promise<Object>} response
*/
function apiJson( route, options ) {
	return fetchJson( API_ROOT + route, {
		'fetchImpl': options.fetchImpl,
		'headers': apiHeaders( options.token ),
		'maxRetries': options.maxRetries,
		'sleep': options.sleep
	} );
}

/**
* Lists all artifacts for a workflow run within a defensive page cap.
*
* @private
* @param {string} project - project locator
* @param {string|number} runId - run identifier
* @param {Object} options - request options
* @returns {Promise<Array>} artifacts
*/
async function listArtifacts( project, runId, options ) {
	var artifacts = [];
	var page;
	var query;
	var result;
	var items;

	for ( page = 1; page <= 10; page += 1 ) {
		query = new URLSearchParams( { 'per_page': '100', 'page': String( page ) } );
		result = await apiJson( '/repos/' + project + '/actions/runs/' + runId + '/artifacts?' + query, options );
		items = result.value.artifacts;
		if ( !Array.isArray( items ) ) {
			throw new HarvesterError( 'GitHub artifacts response is malformed', {
				'code': 'INVALID_PROVIDER_RESPONSE'
			} );
		}
		artifacts.push.apply( artifacts, items );
		if ( items.length < 100 ) {
			return artifacts;
		}
	}
	throw new HarvesterError( 'GitHub artifact pagination limit exceeded', {
		'code': 'PAGINATION_LIMIT'
	} );
}

/**
* Lists completed workflow runs within a defensive page cap.
*
* @private
* @param {string} project - project locator
* @param {string|number} workflowId - workflow identifier
* @param {string} branch - trusted branch
* @param {Object} options - request options
* @returns {Promise<Array>} workflow runs
*/
async function listRuns( project, workflowId, branch, options ) {
	var runs = [];
	var page;
	var query;
	var result;
	var items;

	for ( page = 1; page <= 10; page += 1 ) {
		query = new URLSearchParams( {
			'branch': branch,
			'status': 'completed',
			'per_page': '100',
			'page': String( page )
		} );
		result = await apiJson( '/repos/' + project + '/actions/workflows/' + workflowId + '/runs?' + query, options );
		items = result.value.workflow_runs;
		if ( !Array.isArray( items ) ) {
			throw new HarvesterError( 'GitHub workflow runs response is malformed', {
				'code': 'INVALID_PROVIDER_RESPONSE'
			} );
		}
		runs.push.apply( runs, items );
		if ( items.length < 100 ) {
			return runs;
		}
	}
	throw new HarvesterError( 'GitHub workflow run pagination limit exceeded', {
		'code': 'PAGINATION_LIMIT'
	} );
}


// MAIN //

/**
* Fetches a trusted GitHub Actions artifact and neutral provenance.
*
* @param {Object} context - adapter context
* @returns {Promise<Object>} bytes and origin
*/
async function fetchArtifact( context ) {
	var source = context.source;
	var token = context.token || tokenFor( source, context.env || process.env );
	var options;
	var project;
	var workflow;
	var runs;
	var run;
	var artifacts;
	var matches;
	var artifact;
	var download;
	var actual;

	if ( !token ) {
		throw new HarvesterError( 'No GitHub read token is available for ' + source.project, {
			'code': 'MISSING_CREDENTIAL'
		} );
	}
	options = {
		'fetchImpl': context.fetchImpl,
		'token': token,
		'maxRetries': context.maxRetries,
		'sleep': context.sleep
	};
	project = ( await apiJson( '/repos/' + source.project, options ) ).value;
	if ( !project || project.id === undefined || typeof project.full_name !== 'string' ) {
		throw new HarvesterError( 'GitHub project response is malformed', {
			'code': 'INVALID_PROVIDER_RESPONSE'
		} );
	}
	if ( project.full_name.toLowerCase() !== source.project.toLowerCase() ) {
		throw new HarvesterError( 'GitHub canonical project ' + project.full_name + ' does not match ' + source.project, {
			'code': 'PROJECT_MISMATCH'
		} );
	}
	if ( context.expectedProjectId && String( project.id ) !== String( context.expectedProjectId ) ) {
		throw new HarvesterError( 'GitHub project immutable ID differs from stored source history', {
			'code': 'PROJECT_ID_MISMATCH'
		} );
	}
	workflow = ( await apiJson( '/repos/' + source.project + '/actions/workflows/' + encodeURIComponent( source.selector.workflow ), options ) ).value;
	if ( !workflow || workflow.state !== 'active' || workflow.path !== '.github/workflows/' + source.selector.workflow ) {
		throw new HarvesterError( 'GitHub workflow is missing, inactive, or has an unexpected path: ' + source.selector.workflow, {
			'code': 'INVALID_WORKFLOW'
		} );
	}
	runs = await listRuns( source.project, workflow.id, source.ref.name, options );
	runs = runs.filter( function trusted( candidate ) {
		return candidate && ALLOWED_EVENTS.has( candidate.event ) &&
			String( candidate.head_repository && candidate.head_repository.id ) === String( project.id ) &&
			typeof candidate.head_repository.full_name === 'string' &&
			candidate.head_repository.full_name.toLowerCase() === project.full_name.toLowerCase() &&
			candidate.head_branch === source.ref.name;
	} ).sort( compareRuns );
	if ( runs.length === 0 ) {
		throw new HarvesterError( 'No completed trusted GitHub workflow run was found', {
			'code': 'NO_TRUSTED_RUN'
		} );
	}
	run = runs[ 0 ];
	artifacts = await listArtifacts( source.project, run.id, options );
	matches = artifacts.filter( function matchesArtifact( candidate ) {
		return candidate && candidate.name === source.selector.artifact && !candidate.expired;
	} );
	if ( matches.length !== 1 ) {
		throw new HarvesterError( 'Expected exactly one non-expired artifact named ' + source.selector.artifact + '; found ' + matches.length, {
			'code': 'ARTIFACT_MISMATCH'
		} );
	}
	artifact = matches[ 0 ];
	if ( artifact.id === undefined || !Number.isSafeInteger( Number( artifact.size_in_bytes ) ) || Number( artifact.size_in_bytes ) < 0 ) {
		throw new HarvesterError( 'GitHub artifact response is malformed', {
			'code': 'INVALID_PROVIDER_RESPONSE'
		} );
	}
	if ( Number( artifact.size_in_bytes ) > limits.maxHttpBytes ) {
		throw new HarvesterError( 'GitHub artifact advisory size exceeds the payload limit', {
			'code': 'RESPONSE_TOO_LARGE'
		} );
	}
	download = await fetchBounded( API_ROOT + '/repos/' + source.project + '/actions/artifacts/' + artifact.id + '/zip', {
		'fetchImpl': context.fetchImpl,
		'headers': apiHeaders( token ),
		'maxBytes': limits.maxHttpBytes,
		'maxRetries': context.maxRetries,
		'sleep': context.sleep
	} );
	if ( artifact.digest && artifact.digest.startsWith( 'sha256:' ) ) {
		actual = 'sha256:' + sha256( download.bytes );
		if ( actual !== artifact.digest.toLowerCase() ) {
			throw new HarvesterError( 'GitHub artifact digest verification failed', {
				'code': 'ARTIFACT_DIGEST_MISMATCH'
			} );
		}
	}
	return {
		'bytes': download.bytes,
		'origin': {
			'type': 'ci_artifact',
			'provider': 'github',
			'project': {
				'id': String( project.id ),
				'locator': project.full_name
			},
			'ref': structuredClone( source.ref ),
			'run': Object.assign( {
				'id': String( run.id )
			}, run.head_sha ? { 'revision': String( run.head_sha ) } : {} ),
			'artifact': {
				'id': String( artifact.id ),
				'name': artifact.name
			},
			'provider_details': Object.assign( {
				'workflow': source.selector.workflow,
				'run_attempt': Number( run.run_attempt || 1 )
			}, artifact.created_at ? {
				'artifact_created_at': normalizeTimestamp( artifact.created_at )
			} : {}, artifact.digest && artifact.digest.startsWith( 'sha256:' ) ? {
				'artifact_digest': artifact.digest.toLowerCase()
			} : {} )
		}
	};
}


// EXPORTS //

module.exports = fetchArtifact;
